  "liveDiag.whatBody": "When you go live, the app sends your camera and microphone to the streaming server, which delivers the video to viewers. If anything fails along the way (network, permissions, NAT), viewers get stuck on \"Connecting…\". These are the logs from the last attempt so you (or support) can see exactly where it stopped.",
